// Вилучення структурованих деталей помилки з контексту виконання n8n
const errorData = $input.first().json;

const executionId = errorData.execution?.id || 'unknown_exec';
const workflowName = errorData.workflow?.name || 'unknown_workflow';
const lastNodeExecuted = errorData.execution?.lastNodeExecuted || 'unknown_node';
const errorMessage = errorData.execution?.error?.message || 'Unknown execution failure';
const errorStack = errorData.execution?.error?.stack || '';

// Спроба отримати source_message_id із вхідних даних, якщо він доступний
let sourceMessageId = 'unknown_msg';
try {
  const runData = errorData.execution?.data?.resultData?.runData || {};
  for (const nodeKey of Object.keys(runData)) {
    const nodeItems = runData[nodeKey]?.[0]?.data?.main?.[0] || [];
    if (nodeItems.length > 0 && nodeItems[0].json?.source_message_id) {
      sourceMessageId = nodeItems[0].json.source_message_id;
      break;
    }
  }
} catch (e) {
  // ігнорування помилки інспекції даних
}

return [{
  json: {
    source_message_id: sourceMessageId,
    execution_id: executionId,
    workflow_name: workflowName,
    failed_node: lastNodeExecuted,
    error_message: errorMessage,
    error_type: 'processing_error',
    error_stack: errorStack,
    timestamp: new Date().toISOString()
  }
}];

parameters.query:
UPDATE messages
SET processing_status = 'processing_error'
WHERE source_message_id = $1;

