// Підготовка корисного навантаження сповіщення для чергової команди DevOps On-Call
const item = $('Extract Error Context').first().json;

const alertPayload = {
  channel: '#techops-alerts',
  text: '🚨 *Pipeline Processing Error* in ' + (item.workflow_name || 'workflow'),
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: '🚨 TechOps Triage Pipeline Failure'
      }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: '*Execution ID:* ' + item.execution_id },
        { type: 'mrkdwn', text: '*Failed Node:* ' + item.failed_node },
        { type: 'mrkdwn', text: '*Message ID:* ' + item.source_message_id },
        { type: 'mrkdwn', text: '*Time:* ' + item.timestamp }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '*Error:* ' + item.error_message
      }
    }
  ]
};

return [{ json: alertPayload }];
